draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // dog body
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 + Math.sin(t) * 50, H/2, 20, 0, 2 * Math.PI);
  ctx.fill();

  // dog head
  ctx.beginPath();
  ctx.arc(W/2 + Math.sin(t) * 50, H/2 - 30, 10, 0, 2 * Math.PI);
  ctx.fill();

  // dog ear
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t) * 50 - 10, H/2 - 40);
  ctx.lineTo(W/2 + Math.sin(t) * 50 - 20, H/2 - 50);
  ctx.lineTo(W/2 + Math.sin(t) * 50, H/2 - 40);
  ctx.stroke();

  // dog leg
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t) * 50, H/2 + 20);
  ctx.lineTo(W/2 + Math.sin(t) * 50 - 20 + Math.cos(t) * 10, H/2 + 50);
  ctx.stroke();

  // dog tail
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t) * 50, H/2 + 20);
  ctx.lineTo(W/2 + Math.sin(t) * 50 + Math.cos(t) * 30, H/2 + 50);
  ctx.stroke();

  ctx.restore();
}
